import {createServer} from 'vite';
import vue from '@vitejs/plugin-vue';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import {demoUser,demoRows} from './inventory-role-workspace.js';
const rows=Array.from({length:30},(_,i)=>({...demoRows[i%3],product_id:101+i,product_name:'滚动验证库存 '+(i+1)}));
const orders=Array.from({length:30},(_,i)=>({id:i+1,posting_number:'SCROLL-ORDER-'+(i+1),shop_id:1,shop_name:'验证店铺',status:'awaiting_packaging',ordered_at:'2026-10-31T01:00:00Z',revenue:50,item_count:1,product_names:'验证订单商品',skus:'SKU-'+i,sku_quantities:'SKU-'+i+':1',fulfillment_type_label:'FBS',logistics_carrier_label:'OGL'}));
const shell=`<script setup>
import {ref} from 'vue';import {usePagedWorkspaceLayout} from '/frontend/admin/composables/usePagedWorkspaceLayout.js';
const panel=ref(null);usePagedWorkspaceLayout(panel);
</script><template><div class="erp-shell" style="height:100vh;display:flex;flex-direction:column"><header style="height:54px;flex:none;padding:15px">列表滚动验证 · 仅演示数据</header><main class="erp-content" style="flex:1;min-height:0"><div class="erp-content-inner"><nav class="erp-workspace-tabs"><span>订单处理 · 库存 · 采购</span></nav><div class="erp-workspace-panels"><div class="erp-workspace-panel" ref="panel"><router-view/></div></div></div></main></div></template>`;
const fixture=`<script setup>
import {ref} from 'vue';import PageFooterPagination from '/frontend/admin/components/PageFooterPagination.vue';
const page=ref(1),rows=ref(Array.from({length:40},(_,i)=>({id:i+1,name:'库存商品 '+(i+1)}))),dialog=ref(false),tab=ref('list');window.layoutFixture={rows,dialog,tab};
</script><template><div class="page-stack"><el-tabs v-model="tab"><el-tab-pane name="list" label="列表"><el-card class="page-card"><div class="filter-panel"><el-input aria-label="库存精确搜索" placeholder="库存搜索" style="width:250px"/><el-button @click="dialog=true">打开库存详情</el-button></div><div class="erp-responsive-table"><el-table :data="rows" height="650" border><el-table-column prop="id" label="编号" width="100"/><el-table-column prop="name" label="库存商品" min-width="1400"/></el-table></div><PageFooterPagination :total="200" :page="page" @update:page="page=$event"/></el-card></el-tab-pane><el-tab-pane name="report" label="普通报表"><div style="height:1500px">非列表页面保留页面滚动</div></el-tab-pane></el-tabs><el-dialog v-model="dialog" title="库存详情"><el-table :data="rows" height="200"><el-table-column prop="name" label="明细"/></el-table><PageFooterPagination :total="200" :page="1"/></el-dialog></div></template>`;
const entry=`import {createApp} from 'vue';import {createPinia} from 'pinia';import {createRouter,createWebHashHistory} from 'vue-router';import ElementPlus from 'element-plus';import 'element-plus/dist/index.css';import '/frontend/admin/styles/index.css';import '/frontend/admin/styles/erp-theme.css';import '/frontend/admin/styles/paged-workspace.css';import Shell from '/__layout/Shell.vue';import Fixture from '/__layout/Fixture.vue';import Orders from '/frontend/admin/views/orders/OrdersView.vue';import Procurement from '/frontend/admin/views/procurement/ProcurementWorkspaceView.vue';import Collector from '/frontend/admin/views/listing/CollectorBoxView.vue';import Products from '/frontend/admin/views/inventory/InventoryProductsPage.vue';import {useAuthStore} from '/frontend/admin/stores/auth.js';import {setAuthToken} from '/frontend/admin/utils/api.js';const pinia=createPinia(),app=createApp(Shell);app.use(pinia);const auth=useAuthStore();auth.user=${JSON.stringify(demoUser)};setAuthToken('layout-test');localStorage.setItem('baodanAuthUser',JSON.stringify(auth.user));const router=createRouter({history:createWebHashHistory(),routes:[{path:'/fixture',component:Fixture},{path:'/orders',component:Orders},{path:'/procurement/workspace',component:Procurement},{path:'/collector-box',component:Collector},{path:'/inventory/products',component:Products}]});app.use(router).use(ElementPlus);window.layoutRouter=router;window.layoutErrors=[];app.config.errorHandler=e=>window.layoutErrors.push(e.message);await router.isReady();app.mount('#adminApp');`;
export async function startPagedWorkspacePreview({apiHandler,stableDeps=false}={}) {
const cacheDir=await fs.mkdtemp(path.join(os.tmpdir(),'erp-paged-layout-vite-'));
const server=await createServer({configFile:false,root:process.cwd(),publicDir:false,cacheDir,optimizeDeps:{noDiscovery:stableDeps,include:['vue','vue-router','pinia','element-plus','@element-plus/icons-vue']},logLevel:'error',server:{host:'127.0.0.1',port:8788,strictPort:true},plugins:[vue(),{name:'layout-fixture',resolveId(id){if(id.startsWith('/__layout/'))return id;},load(id){return {'/__layout/Shell.vue':shell,'/__layout/Fixture.vue':fixture,'/__layout/entry.js':entry}[id];},configureServer(server){server.middlewares.use((req,res,next)=>{const url=new URL(req.url,'http://localhost');const send=data=>{res.setHeader('content-type','application/json');res.end(JSON.stringify(data));};if(apiHandler?.(req,res,url,send))return;if(url.pathname==='/admin.html'){res.setHeader('content-type','text/html');return res.end('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body><div id="adminApp"></div><script type="module" src="/__layout/entry.js"></script></body></html>');}if(!url.pathname.startsWith('/api/'))return next();if(req.method!=='GET'){res.statusCode=405;return send({error:'layout fixture does not write business data'});}if(url.pathname.endsWith('/image')){res.setHeader('content-type','image/svg+xml');return res.end('<svg xmlns="http://www.w3.org/2000/svg" width="64" height="84"><rect width="64" height="84" fill="#8a9bad"/></svg>');}if(url.pathname==='/api/orders')return send({rows:orders,total:200,page:1,pageSize:30,counts:{all:200,awaiting_packaging:200}});if(url.pathname==='/api/shops')return send([{id:1,name:'验证店铺'}]);if(url.pathname==='/api/inventory-workflow/purchase-arrivals')return send({rows:rows.map((r,i)=>({id:i+1,product_id:r.product_id,product_name:r.product_name,quantity:10,arrival_state:'open',purchased_at:'2026-10-30 01:00:00'})),total:200,summary:{open:200,arrived:0}});if(url.pathname==='/api/inventory-workflow')return send({rows,total:200,summary:{required:50,advisory:30},meta:{required:50,advisory:30},snapshot:{available:true,calculated_at:'2026-10-31T01:00:00Z'}});if(url.pathname==='/api/products')return send({rows:rows.map(r=>({id:r.product_id,name:r.product_name,inventory_number:r.inventory_number,local_stock:5,unit:'件',images:[]})),total:200,page:1,pageSize:30});if(url.pathname.includes('collector'))return send({rows:rows.map(r=>({sku:String(r.product_id),title:r.product_name,platform:'ozon',images:[],status:'pending'})),total:200});return send({rows:[],total:0});});}}]});await server.listen();return server;
}

